<?php require_once __DIR__.'/../includes/admin-auth.php';$pageTitle='Events';$q=trim($_GET['q']??'');$s=$pdo->prepare("SELECT e.*,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status='valid') registered FROM events e WHERE e.title LIKE ? ORDER BY e.event_date DESC");$s->execute(['%'.$q.'%']);$events=$s->fetchAll();require __DIR__.'/../includes/admin-layout.php'; ?><div class="panel"><div class="d-flex justify-content-between align-items-center flex-wrap gap-3 mb-3"><form class="d-flex gap-2" data-validate novalidate data-no-lock><input class="form-control" maxlength="80" name="q" value="<?=e($q)?>" placeholder="Search events"><button class="btn btn-outline-primary">Search</button></form><a href="create-event.php" class="btn btn-primary"><i class="bi bi-plus-lg me-1"></i>Create event</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Event</th><th>Date</th><th>Category</th><th>Capacity</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($events as $ev): ?><tr><td><strong><?=e($ev['title'])?></strong><div class="small muted"><?=e($ev['venue'])?></div></td><td><?=e(date('M j, Y',strtotime($ev['event_date'])))?></td><td><?=e($ev['category'])?></td><td><?=e($ev['registered'])?> / <?=e($ev['capacity'])?></td><td><span class="status-pill status-<?=e($ev['status'])?>"><?=e($ev['status'])?></span></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="edit-event.php?id=<?=(int)$ev['id']?>">Edit</a> <a class="btn btn-sm btn-outline-secondary" href="event-view.php?id=<?=(int)$ev['id']?>">View</a> <?php if(in_array($_SESSION['admin_role'],['super_admin','event_admin'],true)): ?><form method="post" action="delete-event.php" class="d-inline" onsubmit="return confirm('Cancel this event? Existing registrations will be retained.');"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$ev['id']?>"><button class="btn btn-sm btn-outline-danger">Cancel</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$events): ?><tr><td colspan="6" class="text-center muted">No events found.</td></tr><?php endif; ?></tbody></table></div></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
